shapes={(4,3):1,(2,2):2,(3,2):2,(3,1):2,(6,2):1,(2,1):3,(4,2):1,(1,1):3}
# rectangles unrotated; require all count except one singleton
placements_bycell={}
for h,w in shapes:
    placements=[]
    for r in range(mask.shape[0]-h+1):
        for c in range(mask.shape[1]-w+1):
            cells=tuple((rr,cc) for rr in range(r,r+h) for cc in range(c,c+w))
            if all(mask[rr,cc] for rr,cc in cells): placements.append((r,c,cells,(h,w)))
    print((h,w), len(placements), [(p[0],p[1]) for p in placements[:8]])

# recursive exact cover with all nonsingles and exactly 2 singles (third unused)
placements={}
for shape in shapes:
    h,w=shape; pl=[]
    for r in range(mask.shape[0]-h+1):
        for c in range(mask.shape[1]-w+1):
            cells=tuple(rr*mask.shape[1]+cc for rr in range(r,r+h) for cc in range(c,c+w))
            if all(mask[rr,cc] for rr in range(r,r+h) for cc in range(c,c+w)):
                bits=sum(1<<x for x in cells)
                pl.append((r,c,bits,cells))
    placements[shape]=pl
full=sum(1<<(r*20+c) for r,c in zip(*np.where(mask)))
# map row-major first uncovered
from functools import lru_cache
counts0=(1,2,2,2,1,3,1,2) # ordered shapes list below
shape_order=[(4,3),(2,2),(3,2),(3,1),(6,2),(2,1),(4,2),(1,1)]
counts0=tuple(shapes[s] - (1 if s==(1,1) else 0) for s in shape_order)
@lru_cache(None)
def solve(covered, counts):
    if covered==full:
        return ((),) if not any(counts) else ()
    # choose first uncovered
    rem=full & ~covered
    first=(rem & -rem).bit_length()-1
    rr,cc=divmod(first,20)
    results=[]
    for i,s in enumerate(shape_order):
        if counts[i]<=0: continue
        h,w=s
        for r,c,bits,cells in placements[s]:
            if r!=rr or c!=cc: continue
            if bits & covered: continue
            ccnt=list(counts); ccnt[i]-=1
            for tail in solve(covered|bits,tuple(ccnt)):
                results.append(((s,r,c),)+tail)
                if len(results)>=1000: return tuple(results)
    return tuple(results)
res=solve(0,counts0)
len(res), counts0, solve.cache_info()

# make placements by base piece shape, allowing 90-degree rotation
rotplacements={}
for base in shapes:
    orientations={base,(base[1],base[0])}
    pl=[]
    for h,w in orientations:
        for r in range(mask.shape[0]-h+1):
            for c in range(mask.shape[1]-w+1):
                cells=tuple(rr*20+cc for rr in range(r,r+h) for cc in range(c,c+w))
                if all(mask[rr,cc] for rr in range(r,r+h) for cc in range(c,c+w)):
                    bits=sum(1<<x for x in cells)
                    pl.append((r,c,bits,cells,(h,w)))
    rotplacements[base]=pl
@lru_cache(None)
def solve_rot(covered, counts):
    if covered==full:
        return ((),) if not any(counts) else ()
    rem=full & ~covered
    first=(rem & -rem).bit_length()-1
    rr,cc=divmod(first,20)
    results=[]
    for i,s in enumerate(shape_order):
        if counts[i]<=0: continue
        for r,c,bits,cells,orient in rotplacements[s]:
            if r!=rr or c!=cc or bits&covered: continue
            ccnt=list(counts);ccnt[i]-=1
            for tail in solve_rot(covered|bits,tuple(ccnt)):
                results.append(((s,r,c,orient),)+tail)
                if len(results)>=100: return tuple(results)
    return tuple(results)
resrot=solve_rot(0,counts0)
len(resrot),solve_rot.cache_info()

