for base in [(6,2),(4,3),(4,2),(3,2),(3,1),(2,2),(2,1),(1,1)]:
  print('\n',base)
  for r,c,bits,cells,ori in rotplacements[base]:
    print((r,c,ori),end=' ')
  print()

# placements lists include only contained in full mask, same as rotplacements
# candidate index by each cell, with object base shape + actual bbox dims + bitmask
allpl=[]; plcover={i:[] for i in range(140)}
for si,s in enumerate(shape_order):
    for r,c,bits,cells,ori in rotplacements[s]:
        idx=len(allpl); allpl.append((si,s,r,c,bits,ori))
        for cell in cells: plcover[cell].append(idx)
countsall=tuple(shapes[s] for s in shape_order)
@lru_cache(None)
def solve_overlap(covered, counts, overlapleft):
    if covered==full:
        return ((),) if not any(counts) and overlapleft==0 else ()
    rem=full & ~covered
    first=(rem & -rem).bit_length()-1
    results=[]
    for idx in plcover[first]:
        si,s,r,c,bits,ori=allpl[idx]
        if counts[si]<=0: continue
        ov=(bits&covered).bit_count()
        if ov>overlapleft: continue
        newbits=bits&~covered
        if not newbits: continue
        ccnt=list(counts);ccnt[si]-=1
        for tail in solve_overlap(covered|bits,tuple(ccnt),overlapleft-ov):
            results.append(((s,r,c,ori,ov),)+tail)
            if len(results)>=10: return tuple(results)
    return tuple(results)
ovres=solve_overlap(0,countsall,1)
len(ovres),solve_overlap.cache_info()

